function encodeRFC3986(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, function (character) {
    return "%" + character.charCodeAt(0).toString(16).toUpperCase();
  });
}

function serializeQuery(pairs) {
  if (!Array.isArray(pairs)) {
    throw new TypeError();
  }

  const encodedPairs = [];

  for (let index = 0; index < pairs.length; index += 1) {
    if (!Object.prototype.hasOwnProperty.call(pairs, index)) {
      throw new TypeError();
    }

    const pair = pairs[index];

    if (
      !Array.isArray(pair) ||
      pair.length !== 2 ||
      !Object.prototype.hasOwnProperty.call(pair, 0) ||
      !Object.prototype.hasOwnProperty.call(pair, 1)
    ) {
      throw new TypeError();
    }

    const name = pair[0];
    const value = pair[1];

    if (typeof name !== "string" || typeof value !== "string") {
      throw new TypeError();
    }

    encodedPairs.push([encodeRFC3986(name), encodeRFC3986(value), index]);
  }

  encodedPairs.sort(function (left, right) {
    if (left[0] !== right[0]) {
      return left[0] < right[0] ? -1 : 1;
    }
    if (left[1] !== right[1]) {
      return left[1] < right[1] ? -1 : 1;
    }
    return left[2] - right[2];
  });

  let result = "";
  for (let index = 0; index < encodedPairs.length; index += 1) {
    if (index > 0) {
      result += "&";
    }
    result += encodedPairs[index][0] + "=" + encodedPairs[index][1];
  }

  return result;
}
